# owner: platform
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.models import Student


def make(ident, last, first, section, email):
    return Student(ident, last, first, section, email)


class ContactTests(unittest.TestCase):
    def test_rows_sorted_and_aligned(self):
        rows = contact_rows([
            make("2", "Young", "Al", "B", "al@x.org"),
            make("1", "Adams", "Beth", "A", "beth@x.org")
        ])
        self.assertEqual(rows, [
            "Adams, Beth  A  beth@x.org",
            "Young, Al    B  al@x.org"
        ])

    def test_missing_email_names_student(self):
        with self.assertRaises(ValueError) as caught:
            contact_rows([
                make("1", "Adams", "Beth", "A", None)
            ])
        self.assertIn("Adams, Beth", str(caught.exception))

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            contact_rows([])
